  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Fabiola Gianotti",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The Higgs boson discovery completed a central piece of the Standard Model and opened direct study of the mechanism giving elementary particles mass. Its scientific importance and experimental confirmation are exceptional.",
        "attribution": "The result came from two enormous collaborations, so individual credit is intrinsically difficult. These proposed names represent leadership across the experiments; any final attribution would require careful review of the collaboration's work and leadership.",
        "maturity": "The boson was discovered in 2012 and its properties have since been measured in multiple production and decay channels. The result is firmly established.",
        "uncertainties": [
          "The boundary between individual leadership and the collective achievement of ATLAS and CMS is difficult to draw fairly."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page",
        "David N. Spergel"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precise mapping of the cosmic microwave background turned cosmology into a precision science and constrained the age, composition, and history of the universe.",
        "attribution": "Bennett and Page represent the mission's experimental leadership, while Spergel contributed substantially to interpreting the cosmological results. The mapping depended on a broad mission team.",
        "maturity": "The measurements have been extensively checked and broadly corroborated by later CMB observations. Their cosmological conclusions remain foundational.",
        "uncertainties": [
          "The proposed names cannot capture the full contributions of the WMAP team or the complementary role of later CMB experiments."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Heino Falcke",
        "Sheperd S. Doeleman",
        "Ramesh Narayan"
      ],
      "assessment": {
        "nobel_worthiness": "Event Horizon Telescope imaging made black hole scale structure directly accessible and demonstrated a remarkable new form of very-long-baseline astronomy. It connects strong-field gravity to observable data.",
        "attribution": "Falcke and Doeleman were central to the vision and experimental realization; Narayan's theoretical work helped interpret the observations. The image itself is a major collaboration achievement.",
        "maturity": "The 2019 image and subsequent observations are supported by extensive analysis and independent checks. The method has produced results for more than one black hole.",
        "uncertainties": [
          "The credit assigned to a few people must be weighed against the many technical and scientific contributions of the EHT collaboration."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "AdS/CFT is a profound gauge-gravity duality that has reshaped theoretical physics and supplied powerful tools for quantum field theory, gravity, and black hole questions.",
        "attribution": "Maldacena's original duality and Witten's influential development and clarification are central contributions. The framework also rests on a wider history of string theory and holographic ideas.",
        "maturity": "The duality has received decades of mathematical development and successful tests in theoretical settings. Its impact is mature within theory, although direct experimental confirmation of the correspondence is absent.",
        "uncertainties": [
          "How much weight to give a transformative framework without direct evidence that nature realizes the proposed duality."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B008",
      "proposed_laureates": [
        "William J. Borucki",
        "David Charbonneau",
        "Gregory W. Henry"
      ],
      "assessment": {
        "nobel_worthiness": "The first exoplanet transits established a robust detection method, and Kepler's census revealed that planetary systems are common and diverse. This changed our picture of planets beyond the Solar System.",
        "attribution": "Borucki led the effort that made Kepler's transit search possible; Charbonneau and Henry were central to early transit detections. The candidate combines distinct milestones, making credit boundaries important.",
        "maturity": "Transit detections have been repeatedly confirmed, and the Kepler population results have been strengthened by later surveys. The discovery field is mature and productive.",
        "uncertainties": [
          "The combined framing spans first detections and a space mission census, whose contributions may warrant different attribution."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle",
        "Christian Spiering"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube's detection of high-energy astrophysical neutrinos opened a new observational window on the universe and established neutrinos as tools for studying energetic cosmic sources.",
        "attribution": "Halzen's leadership and the contributions of Karle and Spiering to the experiment and its development are substantial. The observatory's construction and discovery depended on a large international collaboration.",
        "maturity": "The astrophysical neutrino flux is established through multiple analyses and accumulating observations, while identification of particular source populations is still developing.",
        "uncertainties": [
          "The physical sources and processes responsible for much of the observed flux remain incompletely identified."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological insulators established new phases of matter with protected boundary states, expanding both fundamental condensed matter physics and prospects for quantum devices.",
        "attribution": "Kane and Mele supplied key theoretical predictions, while Molenkamp's experiments provided decisive realization of the quantum spin Hall state. This is a strong theory-experiment attribution.",
        "maturity": "The phase and its characteristic transport signatures have been demonstrated and studied in multiple materials, though practical device advantages remain material-dependent.",
        "uncertainties": [
          "The long-term technological significance is less settled than the conceptual importance of the discovery."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Andrew Strominger",
        "Cumrun Vafa",
        "Juan Maldacena"
      ],
      "assessment": {
        "nobel_worthiness": "The microscopic accounting of black hole entropy was a major advance in quantum gravity, connecting gravitational thermodynamics to underlying quantum states and strengthening the holographic perspective.",
        "attribution": "Strominger and Vafa's state counting and Maldacena's holographic framework made distinct, complementary contributions to the connection described here.",
        "maturity": "The results are influential and have been developed extensively in theoretical models, but their assumptions and limited direct contact with astrophysical black holes constrain empirical confirmation.",
        "uncertainties": [
          "Whether the model-specific microscopic counting captures the entropy of realistic black holes in our universe remains open."
        ]
      }
    }
  ]
}
